package com.mohymods.kingdomsmp.profession;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import com.google.gson.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.contribution.ContributionService;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.storage.LevelResource;
/** Human prior authorization, preserved surroundings and current working geometry. Never destroys any block. */
public final class MineExcavation {
 public static final String PROJECT="kingdom_smp:miner/m07",FINAL="kingdom_smp:miner/m08";
 private record Review(UUID nonce,UUID player,long revision,long issued,MineExcavationSite site,String snapshot){}
 private static final Map<ServerPlayer,Review> REVIEWS=new WeakHashMap<>();
 private static final Set<Block> DIGGABLE=Set.of(Blocks.STONE,Blocks.DIRT,Blocks.COARSE_DIRT,Blocks.COBBLESTONE,Blocks.ANDESITE,Blocks.DIORITE,Blocks.GRANITE,Blocks.DEEPSLATE,Blocks.TUFF);
 private MineExcavation(){}public static boolean contains(String id){return PROJECT.equals(id)||FINAL.equals(id);}
 public static boolean eligible(ServerPlayer p){var r=CommerceService.store(p.server).professions(p.getUUID());return TreeQuestService.real(p)&&p.serverLevel().dimension()==Level.OVERWORLD&&r.isActive(Profession.MINER)&&r.progressBand(Profession.MINER)==ProfessionRank.MASTER&&ContributionService.kingdom(p.server).attainedTier()>=5&&com.mohymods.kingdomsmp.building.ConstructionService.store(p.server).projects().stream().anyMatch(q->q.phase()==com.mohymods.kingdomsmp.persistence.ConstructionStore.Phase.COMPLETE&&!q.npcDead()&&q.blueprint().toString().equals(Profession.MINER.buildingId()));}
 public static Optional<UUID> currentReview(ServerPlayer admin){var r=REVIEWS.get(admin);return admin.hasPermissions(2)&&r!=null?Optional.of(r.nonce()):Optional.empty();}
 private static void attend(ServerPlayer admin,ServerPlayer p,MineExcavationSite site){if(!admin.hasPermissions(2)||admin instanceof net.neoforged.neoforge.common.util.FakePlayer||!admin.isAlive()||admin.server.getPlayerList().getPlayer(admin.getUUID())!=admin||admin.server!=p.server||admin.serverLevel()!=p.serverLevel()||!eligible(p)||admin.distanceToSqr(centerOf(site))>256||p.distanceToSqr(centerOf(site))>1024)throw new IllegalStateException("Living OP2 administrator and eligible survival Miner must attend the site");}
 private static net.minecraft.world.phys.Vec3 centerOf(MineExcavationSite s){return new net.minecraft.world.phys.Vec3((s.from().getX()+s.to().getX()+1)/2.0,(s.from().getY()+s.to().getY()+1)/2.0,(s.from().getZ()+s.to().getZ()+1)/2.0);}
 private static int minimum(ServerPlayer p)throws java.io.IOException{return minimum(p.server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-excavation.json"));}
 static int minimum(Path path)throws java.io.IOException{if(!Files.exists(path)){Files.createDirectories(path.getParent());Files.writeString(path,"{\"schema\":1,\"minimumVolume\":64}\n",StandardOpenOption.CREATE_NEW);}try{var row=JsonParser.parseString(Files.readString(path)).getAsJsonObject();if(!row.keySet().equals(Set.of("schema","minimumVolume"))||number(row,"schema")!=1)throw new IllegalArgumentException("Unknown excavation rules");int n=number(row,"minimumVolume");if(n<8||n>512)throw new IllegalArgumentException("Excavation minimum outside8..512");return n;}catch(RuntimeException e){throw new java.io.IOException("Malformed excavation rules; file preserved",e);}}
 private static int number(JsonObject row,String key){var value=row.get(key);if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("Integer required");return value.getAsBigDecimal().intValueExact();}
 private static String hash(String text){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private static String scan(ServerPlayer p,MineExcavationSite site,boolean before){var level=p.serverLevel();if(!site.dimension().equals(level.dimension().location().toString()))throw new IllegalStateException("Visit the authorized Overworld site");var from=site.from().below().north().west();var to=site.to().above().south().east();if(level.isOutsideBuildHeight(from)||level.isOutsideBuildHeight(to)||!level.getWorldBorder().isWithinBounds(from)||!level.getWorldBorder().isWithinBounds(to))throw new IllegalStateException("Site and protected margin must remain inside world limits");for(var pos:BlockPos.betweenClosed(from,to))if(!level.hasChunkAt(pos))throw new IllegalStateException("Visit the whole excavation; no chunk loading is performed");if(PlacementProtection.check(level,p,from,to)!=null)throw new IllegalStateException("Current excavation or protected-margin claim permission unavailable");LayeredInteriorInspection.requirePlayerProject(p,from,to);var outside=new StringBuilder();var inside=new StringBuilder();for(var cursor:BlockPos.betweenClosed(from,to)){var pos=cursor.immutable();var state=level.getBlockState(pos);if(level.getBlockEntity(pos)!=null)throw new IllegalStateException("Choose a site away from block entities; no storage or workstation may be excavated");if(site.contains(pos)){if(before?!DIGGABLE.contains(state.getBlock()):!state.isAir())throw new IllegalStateException(before?"Authorize an uncleared stone/dirt site; valuable materials and existing holes cannot substitute":"Excavate the authorized volume without destroying its surrounding margin");inside.append(pos.asLong()).append('=').append(state).append(';');}else outside.append(pos.asLong()).append('=').append(state).append(';');}String surrounding=hash(outside.toString());if(!before&&!surrounding.equals(site.surroundings()))throw new IllegalStateException("Protected surroundings changed; restore the authorized site before inspection");return surrounding+":"+hash(inside.toString());}
 public static UUID review(ServerPlayer admin,ServerPlayer p,BlockPos from,BlockPos to,String reason)throws java.io.IOException{var store=CommerceService.store(p.server);var r=store.professions(p.getUUID());if(r.track(Profession.MINER).completedQuestIds().contains(PROJECT)||!InspectionQuests.catalog().mayAttempt(Profession.MINER,PROJECT,r.track(Profession.MINER).completedQuestIds()))throw new IllegalStateException("Complete the approved prior trials before authorizing excavation");var provisional=new MineExcavationSite(UUID.randomUUID(),admin.getUUID(),p.getUUID(),p.serverLevel().dimension().location().toString(),from,to,"0".repeat(64),reason);attend(admin,p,provisional);if(provisional.volume()<minimum(p))throw new IllegalStateException("Select at least the configured volume of solid stone/dirt");var entry=BlockPos.of(MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).orElseThrow().cells().getFirst());if(centerOf(provisional).distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(entry))>576)throw new IllegalStateException("Choose a site within24blocks of your authenticated mine entrance");String snapshot=scan(p,provisional,true);var site=new MineExcavationSite(provisional.id(),admin.getUUID(),p.getUUID(),provisional.dimension(),from,to,snapshot.substring(0,64),reason);REVIEWS.put(admin,new Review(site.id(),p.getUUID(),store.revision(),System.nanoTime(),site,snapshot));return site.id();}
 public static void confirm(ServerPlayer admin,UUID nonce)throws java.io.IOException{var r=REVIEWS.remove(admin);var store=CommerceService.store(admin.server);if(r==null||!r.nonce().equals(nonce)||r.revision()!=store.revision()||System.nanoTime()-r.issued()>30_000_000_000L)throw new IllegalStateException("Excavation review expired; review again");var p=admin.server.getPlayerList().getPlayer(r.player());if(p==null)throw new IllegalStateException("Miner must remain online");attend(admin,p,r.site());if(r.site().volume()<minimum(p)||!scan(p,r.site(),true).equals(r.snapshot()))throw new IllegalStateException("Site changed after review; no authorization recorded");store.authorizeMineExcavation(r.site());com.mojang.logging.LogUtils.getLogger().info("MINE_EXCAVATION_AUTHORIZATION actor={} player={} site={} purpose={}",admin.getUUID(),p.getUUID(),r.site().id(),r.site().reason());}
 private static String connection(ServerPlayer p,MineExcavationSite site){var level=p.serverLevel();var entry=BlockPos.of(MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).orElseThrow().cells().getFirst());var floor=site.from().below();for(var point:BlockPos.betweenClosed(floor,new BlockPos(site.to().getX(),floor.getY(),site.to().getZ())))if(!level.getBlockState(point).isFaceSturdy(level,point,Direction.UP))throw new IllegalStateException("Maintain a solid floor under the excavation");var nodes=new TreeMap<Long,String>();var from=new BlockPos(Math.min(entry.getX(),site.from().getX())-2,Math.min(entry.getY(),floor.getY())-2,Math.min(entry.getZ(),site.from().getZ())-2);var to=new BlockPos(Math.max(entry.getX(),site.to().getX())+2,Math.max(entry.getY(),floor.getY())+2,Math.max(entry.getZ(),site.to().getZ())+2);for(var cursor:BlockPos.betweenClosed(from,to)){var pos=cursor.immutable();if(!level.hasChunkAt(pos)||level.isOutsideBuildHeight(pos)||level.isOutsideBuildHeight(pos.above(2))||!level.getWorldBorder().isWithinBounds(pos))continue;var state=level.getBlockState(pos);if(!state.getFluidState().isEmpty()||!state.canSurvive(level,pos)||!(state.isFaceSturdy(level,pos,Direction.UP)||state.getBlock() instanceof StairBlock||state.getBlock() instanceof SlabBlock)||!level.getBlockState(pos.above()).getCollisionShape(level,pos.above()).isEmpty()||!level.getBlockState(pos.above(2)).getCollisionShape(level,pos.above(2)).isEmpty()||!level.getFluidState(pos.above()).isEmpty()||PlacementProtection.check(level,p,pos,pos.above(2))!=null)continue;try{LayeredInteriorInspection.requirePlayerProject(p,pos,pos.above(2));}catch(IllegalStateException denied){continue;}if(nodes.size()>=4096)throw new IllegalStateException("Access exceeds4096nodes; choose a compact mine project");nodes.put(pos.asLong(),state.toString());}var queue=new ArrayDeque<BlockPos>();var visited=new HashSet<Long>();if(nodes.containsKey(entry.asLong())){queue.add(entry);visited.add(entry.asLong());}boolean reaches=false;while(!queue.isEmpty()){var pos=queue.removeFirst();if(pos.getY()==floor.getY()&&pos.getX()>=site.from().getX()&&pos.getX()<=site.to().getX()&&pos.getZ()>=site.from().getZ()&&pos.getZ()<=site.to().getZ())reaches=true;for(var side:Direction.Plane.HORIZONTAL)for(int dy=-1;dy<=1;dy++){var next=pos.relative(side).offset(0,dy,0);if(nodes.containsKey(next.asLong())&&visited.add(next.asLong()))queue.add(next);}}if(!reaches)throw new IllegalStateException("Provide loaded dry supported clear access connecting the genuine entrance to the excavated floor");return hash(nodes.toString());}
 public static String completedSnapshot(ServerPlayer admin,ServerPlayer p,String id,BlockPos center){var site=CommerceService.store(p.server).mineExcavation(p.getUUID()).orElseThrow(()->new IllegalStateException("Obtain confirmed on-site authorization before excavation"));attend(admin,p,site);String current=scan(p,site,false);String access=MineInspection.validate(p,MinePlan.QUEST,center)+connection(p,site);if(FINAL.equals(id)){if(NativeGeology.count(p)<1||NativeOreSavedData.get(p.server).evidence().regionalCount(p.getUUID(),ProfessionRank.MASTER,"diamond",3)<1)throw new IllegalStateException("Restore matching geology and regional extraction records");for(String quest:NetherOres.GOALS.keySet())if(NetherOres.count(p,quest)<1)throw new IllegalStateException("Restore matching Nether expedition records");for(String metric:List.of("iron","gold","redstone","lapis"))if(NativeOreSavedData.get(p.server).evidence().count(p.getUUID(),ProfessionRank.MASTER,metric)<1)throw new IllegalStateException("Restore matching native specimen records");}return "exc="+site.id().toString().substring(0,8)+",v="+site.volume()+",proof="+hash(site.id()+current+access).substring(0,32);}
}
